'use client';

import { useEffect, useState } from 'react';
import axios from 'axios';
import dayjs from 'dayjs';
import relativeTime from 'dayjs/plugin/relativeTime';
dayjs.extend(relativeTime);

type TrendItem = {
  title: string;
  url: string;
  source_key: string;
  points: number;
  trending_score: number;
  computed_at: string;
};

export default function Home() {
  const [data, setData] = useState<TrendItem[]>([]);
  const [loading, setLoading] = useState(true);

  async function fetchData() {
    try {
      const res = await axios.get(`${process.env.NEXT_PUBLIC_API_URL}/trending?window=24h`);
      setData(res.data);
      setLoading(false);
    } catch (err) {
      console.error(err);
      setLoading(false);
    }
  }

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 60000); // auto-refresh every 60s
    return () => clearInterval(interval);
  }, []);

  if (loading) {
    return <div className="text-gray-400 text-center mt-20">Loading trends...</div>;
  }

  return (
    <main className="min-h-screen bg-gray-950 text-gray-100 flex flex-col items-center py-10">
      <h1 className="text-3xl font-bold mb-8 text-orange-400">InsightRelay — Trending Now</h1>
      <div className="w-full max-w-3xl space-y-3">
        {data.map((item, i) => (
          <a
            key={i}
            href={item.url}
            target="_blank"
            rel="noopener noreferrer"
            className="block border border-gray-800 rounded-lg hover:bg-gray-900 transition p-4"
          >
            <div className="flex justify-between">
              <h2 className="text-lg font-semibold">{item.title}</h2>
              <span className="text-orange-400 font-mono text-sm">
                {item.points} pts
              </span>
            </div>
            <div className="text-sm text-gray-500 mt-1">
              {item.source_key.toUpperCase()} · score {item.trending_score.toFixed(2)} ·{' '}
              {dayjs(item.computed_at).fromNow()}
            </div>
          </a>
        ))}
      </div>
      <footer className="mt-10 text-gray-600 text-sm">
        Auto-refreshing every 60 seconds
      </footer>
    </main>
  );
}
